// Native all-catalog mock candidate. No external endpoints or real tokens.
use serde::{Deserialize,Serialize};use serde_json::{Value,json};use std::{time::{Duration,Instant},net::TcpStream,io::Read,thread,sync::{Mutex,atomic::{AtomicUsize,Ordering}}};
#[derive(Deserialize)]struct Spec{base:String,tls_addr:String,ca:String,generated_at:String,slot:i64,lease:String,catalog:Value}
#[derive(Clone,Deserialize)]struct Check{id:String,kind:String}
#[derive(Serialize)]struct Row{id:String,status:String,checked_at:String,latency_ms:Option<u128>,#[serde(skip_serializing_if="Option::is_none")]http_code:Option<u16>}
fn probe(c:&Check,s:&Spec,client:&reqwest::blocking::Client,tls:&native_tls::TlsConnector)->Row{
 let mut r=Row{id:c.id.clone(),status:"unknown".into(),checked_at:s.generated_at.clone(),latency_ms:None,http_code:None};
 if c.kind=="music_ynison"||matches!(c.id.as_str(),"maps-geocoder"|"ai-speech"|"ai-vision"){r.status="disabled".into();return r}
 let start=Instant::now();r.status="down".into();
 if c.kind=="tcp_tls"{let addr=s.tls_addr.parse().unwrap();if let Ok(sock)=TcpStream::connect_timeout(&addr,Duration::from_secs(2)){sock.set_read_timeout(Some(Duration::from_secs(2))).unwrap();sock.set_write_timeout(Some(Duration::from_secs(2))).unwrap();if tls.connect("127.0.0.1",sock).is_ok(){r.status="ok".into();}}r.latency_ms=Some(start.elapsed().as_millis());return r}
 let auth=c.kind.starts_with("music_")||c.kind=="requires_key";assert!(c.id.chars().all(|x|x.is_ascii_alphanumeric()||x=='-'));
 for attempt in 0..2{let mut q=client.get(format!("{}/mock/{}",s.base,c.id));if auth{q=q.header("Authorization","OAuth synthetic-fixture")}let Ok(res)=q.send()else{break};let code=res.status().as_u16();r.http_code=Some(code);let retry=res.headers().contains_key("Retry-After");let mut bytes=vec![];if res.take(393217).read_to_end(&mut bytes).is_err()||bytes.len()>393216{r.status="degraded".into();break}
 if code==503&&!retry&&attempt==0{thread::sleep(Duration::from_millis(10));continue}
 r.status=if !auth {match code{200..=399=>"ok",401|403|404|429=>"degraded",500..=599=>"down",_=>"unknown"}.into()}else if code==401||code==403||code>=500{"down".into()}else if c.id=="wiki-api"&&code==404{"no_data".into()}else if code!=200{"degraded".into()}else{
 let field=match c.id.as_str(){"disk-api"=>"total_space","wiki-api"=>"id","cloud-iam"=>"serviceAccounts","cloud-monitoring"=>"metrics","ai-models"=>"data","music-rest"=>"account","music-history"|"music-queues"=>"items",_=>""};
 match serde_json::from_slice::<Value>(&bytes).ok().and_then(|v|v.get(field).cloned()){None=>"degraded".into(),Some(x) if matches!(c.id.as_str(),"music-history"|"music-queues")=>match x.as_array(){Some(a) if a.is_empty()=>"no_data".into(),Some(_)=>"ok".into(),None=>"degraded".into()},Some(_)=>"ok".into()}
 };break}
 r.latency_ms=Some(start.elapsed().as_millis());r
}
fn main(){let s:Spec=serde_json::from_str(&std::fs::read_to_string(std::env::args().nth(1).unwrap()).unwrap()).unwrap();let u=reqwest::Url::parse(&s.base).unwrap();assert_eq!(u.scheme(),"http");assert_eq!(u.host_str(),Some("127.0.0.1"));assert!(u.username().is_empty()&&u.password().is_none()&&u.path()=="/"&&u.query().is_none());assert!(s.tls_addr.starts_with("127.0.0.1:"));let client=reqwest::blocking::Client::builder().no_proxy().timeout(Duration::from_secs(2)).redirect(reqwest::redirect::Policy::none()).pool_max_idle_per_host(8).build().unwrap();let tls=native_tls::TlsConnector::builder().min_protocol_version(Some(native_tls::Protocol::Tlsv12)).add_root_certificate(native_tls::Certificate::from_pem(s.ca.as_bytes()).unwrap()).build().unwrap();let checks:Vec<Check>=serde_json::from_value(s.catalog["checks"].clone()).unwrap();let start=Instant::now();let mut first=vec![];let mut rest=vec![];for(i,c)in checks.iter().enumerate(){if c.id=="music-rest"{first.push((i,probe(c,&s,&client,&tls)))}else{rest.push((i,c))}}
 let out=Mutex::new(first);let next=AtomicUsize::new(0);thread::scope(|scope|{for _ in 0..8{let (next,rest,s,client,tls,out)=(&next,&rest,&s,&client,&tls,&out);scope.spawn(move||loop{let i=next.fetch_add(1,Ordering::Relaxed);let Some((j,c))=rest.get(i)else{break};let row=probe(c,s,client,tls);out.lock().unwrap().push((*j,row));});}});let mut rows=out.into_inner().unwrap();rows.sort_by_key(|r|r.0);let mut p=s.catalog.clone();p["generated_at"]=json!(s.generated_at);p["scope"]=json!("Synthetic loopback candidate; NOT Yandex status.");p["results"]=json!(rows.into_iter().map(|x|x.1).collect::<Vec<_>>());let r=client.post(format!("{}/api/ingest",s.base)).json(&json!({"slot":s.slot,"lease":s.lease,"payload":p})).send().unwrap();assert_eq!(r.status(),200);println!("{}",json!({"checks":checks.len(),"engine_publish_ms":start.elapsed().as_secs_f64()*1000.0}));}
